#pragma once

#include <exception>
#include <functional>
#include <memory>

// 前向声明：thenCompose 的实现需要 CompletableFuture 完整类型，
// 其定义放在 CompletableFuture.h 末尾以打破头文件循环依赖。
template<typename T>
class CompletableFuture;

// java.util.concurrent.CompletionStage 模板接口桩。
// 表示异步计算的一个阶段，支持完成回调与链式组合。
template<typename T>
class CompletionStage {
public:
    virtual ~CompletionStage() = default;

    // 注册完成回调：阶段正常或异常完成时触发，返回本阶段
    virtual std::shared_ptr<CompletionStage<T>> whenComplete(
        std::function<void(T, std::exception_ptr)> action) = 0;

    // 链式组合：本阶段完成后以结果为输入执行 fn，返回 fn 产生的新阶段。
    // 非虚函数模板（虚函数不能是模板），定义见 CompletableFuture.h 末尾，
    // 必须在包含 CompletableFuture.h 的翻译单元中实例化。
    template<typename U>
    std::shared_ptr<CompletionStage<U>> thenCompose(
        std::function<std::shared_ptr<CompletionStage<U>>(T)> fn);
};
